{"sql": "SELECT DISTINCT id FROM `bigquery-public-data.ghcn_d.ghcnd_2016` WHERE element = 'PRCP' AND id IN (
  SELECT id FROM `bigquery-public-data.ghcn_d.ghcnd_stations`
  WHERE 6371 * ACOS(
    COS(40.7128 * 3.141592653589793 / 180) * COS(latitude * 3.141592653589793 / 180) * 
    COS((longitude - (-74.0060)) * 3.141592653589793 / 180) + 
    SIN(40.7128 * 3.141592653589793 / 180) * SIN(latitude * 3.141592653589793 / 180)
  ) <= 50
)
ORDER BY id"}

{"sql": "SELECT COUNT(*) as missing_days
FROM (
  SELECT DATE_ADD(DATE('2016-01-01'), INTERVAL n DAY) as all_date
  FROM UNNEST(GENERATE_ARRAY(0, 365)) as n
)
WHERE all_date NOT IN (
  SELECT date
  FROM `bigquery-public-data.ghcn_d.ghcnd_2016`
  WHERE id = 'US1NYKN0025' AND element = 'PRCP' AND qflag IS NULL
)"}
